-- Lists made of lists. NULL elements come last in either order, list_distinct drops them and gives the
-- rest in ascending order, and list_concat is NULL when either list is (vec of row 2 is NULL).
SELECT
  t.nr
, CASE WHEN t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT COLUMN_VALUE FROM TABLE(t.tags) ORDER BY COLUMN_VALUE NULLS LAST) AS SYS.ODCIVARCHAR2LIST) END AS sorted_tags
, CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT COLUMN_VALUE FROM TABLE(t.scores) ORDER BY COLUMN_VALUE DESC NULLS LAST) AS SYS.ODCINUMBERLIST) END AS scores_desc
, CASE WHEN CASE WHEN t.tags IS NULL AND t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT V FROM (SELECT 1 K, ROWNUM R, COLUMN_VALUE V FROM TABLE(t.tags) UNION ALL SELECT 2, ROWNUM, COLUMN_VALUE FROM TABLE(t.tags)) ORDER BY K, R) AS SYS.ODCIVARCHAR2LIST) END IS NULL THEN NULL ELSE CAST(MULTISET(SELECT DISTINCT COLUMN_VALUE FROM TABLE(CASE WHEN t.tags IS NULL AND t.tags IS NULL THEN NULL ELSE CAST(MULTISET(SELECT V FROM (SELECT 1 K, ROWNUM R, COLUMN_VALUE V FROM TABLE(t.tags) UNION ALL SELECT 2, ROWNUM, COLUMN_VALUE FROM TABLE(t.tags)) ORDER BY K, R) AS SYS.ODCIVARCHAR2LIST) END) WHERE COLUMN_VALUE IS NOT NULL ORDER BY COLUMN_VALUE) AS SYS.ODCIVARCHAR2LIST) END AS distinct_tags
, CASE WHEN t.scores IS NULL AND CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X * 10 FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END IS NULL THEN NULL ELSE CAST(MULTISET(SELECT V FROM (SELECT 1 K, ROWNUM R, COLUMN_VALUE V FROM TABLE(t.scores) UNION ALL SELECT 2, ROWNUM, COLUMN_VALUE FROM TABLE(CASE WHEN t.scores IS NULL THEN NULL ELSE CAST(MULTISET(SELECT LA0.X * 10 FROM (SELECT COLUMN_VALUE X, ROWNUM I FROM TABLE(t.scores) Z) LA0 ORDER BY LA0.I) AS SYS.ODCINUMBERLIST) END)) ORDER BY K, R) AS SYS.ODCINUMBERLIST) END AS joined
, CASE WHEN t.vec IS NULL AND t.vec IS NULL THEN NULL ELSE CAST(MULTISET(SELECT V FROM (SELECT 1 K, ROWNUM R, COLUMN_VALUE V FROM TABLE(t.vec) UNION ALL SELECT 2, ROWNUM, COLUMN_VALUE FROM TABLE(t.vec)) ORDER BY K, R) AS SYS.ODCINUMBERLIST) END AS vec_twice
FROM
 check_complex t